{"tool":"write","path":"tests/test_export.py","content":""""Optional tests for reports.export.export_csv."""

import unittest

from reports.export import export_csv


class ExportCsvTest(unittest.TestCase):
    def test_header_and_rows(self):
        out = export_csv(
            [{"a": 1, "b": "x"}, {"a": 2, "b": "y"}],
            ["a", "b"],
        )
        self.assertEqual(out, "a,b\r\n1,x\r\n2,y\r\n")

    def test_quoting_and_doubling(self):
        out = export_csv(
            [{"a": 'say "hi"', "b": "x,y"}],
            ["a", "b"],
        )
        self.assertEqual(out, 'a,b\r\n"say ""hi""","x,y"\r\n')

    def test_embedded_crlf_and_unicode(self):
        out = export_csv([{"a": "p\r\nq\n\r", "b": "caf\u00e9"}], ["a", "b"])
        self.assertEqual(out, 'a,b\r\n"p\r\nq\n\r",caf\u00e9\r\n')

    def test_missing_none_and_unselected(self):
        out = export_csv([{"a": None}, {"b": "no"}], ["a"])
        self.assertEqual(out, "a\r\n\r\n\r\n")

    def test_generators_and_empty_inputs(self):
        self.assertEqual(export_csv(iter(()), (c for c in "ab")), "a,b\r\n")
        self.assertEqual(export_csv(iter(()), iter(())), "\r\n")

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", "a"])

    def test_non_string_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], [1])

    def test_inputs_not_mutated(self):
        rows = [{"a": 1}]
        cols = ["a"]
        export_csv(rows, cols)
        self.assertEqual(rows, [{"a": 1}])
        self.assertEqual(cols, ["a"])


if __name__ == "__main__":
    unittest.main()
